@r1 w.request.request act=make mood=do words="a little blue bird perched up in the top right"
@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=bird
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.at value="top right" operator=region phase=result open_value=true
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.colour value=blue operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=size attribute=drawn.size value=little operator=degree phase=result
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=drawn.pose value="perched up" operator=eq phase=result open_value=true
@r2 w.request.request act=remove mood=do words="clear the rest of the lamps away completely and keep the lamp on the far left untouched" predicate=clear
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=all sort=lamp
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.at value=left want=no operator=region phase=selector
@r2.c2 w.request.constraint request=$r2 on=place attribute=drawn.relation value=on words="on the far" operator=relation phase=result
@r2.c3 w.request.constraint request=$r2 on=place attribute=drawn.anchor value="the far" operator=relation phase=selector
@r2.u1 w.request.unread request=$r2 text="the rest of the lamps away completely and keep the lamp on the far left untouched" note=drawn.keep

@f1 w.request.filler text=then
@f2 w.request.filler text="just that group thins out"
@r1 w.request.request act=make mood=do words="a small brown dog lying down at the bottom edge" predicate=edge
@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=dog
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.at value=bottom words="at the bottom" operator=region phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.colour value=brown operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=size attribute=drawn.size value=small operator=degree phase=result
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=drawn.pose value="lying down" operator=eq phase=result open_value=true
@r2 w.request.request act=remove mood=do words="strip every other lamp out of the picture and leave the lamp on the left exactly as drawn" predicate=strip
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=all sort=lamp
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.at value=left want=no operator=region phase=selector
@r2.u1 w.request.unread request=$r2 text="out of the picture" note=drawn.keep
@r2.u2 w.request.unread request=$r2 text="leave the lamp on the left exactly as drawn" note=page.scope
